Tool response:
Tool: create_booking
Description: Create a new equipment booking
Parameters:
    {
      "type": "object",
      "properties": {
        "user_id": {
          "type": "integer",
          "title": "User Id"
        },
        "department_id": {
          "type": "integer",
          "title": "Department Id"
        },
        "location_id": {
          "type": "integer",
          "title": "Location Id"
        },
        "start_datetime": {
          "type": "string",
          "title": "Start Datetime"
        },
        "end_datetime": {
          "type": "string",
          "title": "End Datetime"
        },
        "recurrence_rule": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Recurrence Rule"
        },
        "recurrence_end_date": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Recurrence End Date"
        },
        "notes": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Notes"
        },
        "booking_items": {
          "items": {
            "properties": {
              "equipment_id": {
                "type": "integer",
                "title": "Equipment Id"
              },
              "quantity": {
                "type": "integer",
                "title": "Quantity"
              }
            },
            "type": "object",
            "required": [
              "equipment_id",
              "quantity"
            ],
            "title": "BookingItemInput"
          },
          "type": "array",
          "title": "Booking Items"
        }
      },
      "required": [
        "user_id",
        "department_id",
        "location_id",
        "start_datetime",
        "end_datetime",
        "booking_items"
      ]
    }

