Tool: find_department_by_name
Description: Retrieve department information by its name.
Parameters:
    {
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "description": "Name of the department",
          "title": "Name"
        }
      },
      "required": [
        "name"
      ]
    }

Tool response:
Tool: find_location_by_name
Description: Retrieve location information by its name.
Parameters:
    {
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "description": "Name of the location",
          "title": "Name"
        }
      },
      "required": [
        "name"
      ]
    }

Tool response:
Tool: find_equipment_by_category_and_availability
Description: Retrieve a list of available equipment items filtered by category name and availability status.
Parameters:
    {
      "type": "object",
      "properties": {
        "category_name": {
          "type": "string",
          "description": "Name of the equipment category",
          "title": "Category Name"
        },
        "is_available": {
          "type": "boolean",
          "description": "Filter by availability status",
          "default": true,
          "title": "Is Available"
        }
      },
      "required": [
        "category_name"
      ]
    }
